class MeasurementView:
    # Zero-copy view over an encoded Measurement; fields are read on access.
    __slots__ = ('_b', '_o', '_p', '_x')
    message_name = 'Measurement'
    min_wire_size = 6

    def __init__(self, b: memoryview, o: list[int] | None = None, p: list[bool] | None = None, x: int = 0) -> None:
        self._b, self._o, self._p, self._x = b, o, p, x

    @staticmethod
    def from_bytes(data) -> MeasurementView:
        """Validate data and build a view. Trailing bytes beyond the message are ignored. Raises gmsg.GmpError."""
        data = gmsg.as_view(data)
        if len(data) < 6: gmsg.fail(Err.TRUNCATED)
        if gmsg.load_uint(data, 2, 1, 'big') != gmsg.checksum.crc8_nrsc5.compute(data, 0, 2): gmsg.fail(Err.BAD_CHECKSUM)
        if gmsg.load_uint(data, 3 + 2, 1, 'big') != gmsg.checksum.crc8_nrsc5.compute(data, 3, 3 + 2): gmsg.fail(Err.BAD_CHECKSUM)
        return MeasurementView(data[:6], None, None, len(data) - 6)

    @staticmethod
    def unchecked(data) -> MeasurementView:
        """A view over data already validated by from_bytes() (no checks)."""
        data = gmsg.as_view(data)
        return MeasurementView(data[:6], None, None, len(data) - 6)

    @property
    def data(self) -> memoryview:
        """The message bytes."""
        return self._b

    @property
    def wire_size(self) -> int:
        return len(self._b)

    @property
    def extra_bytes(self) -> int:
        """Bytes after the message in the data given to from_bytes() (ignored; a protocol with exact_size rejects them)."""
        return self._x

    @property
    def temperature(self) -> int:
        """[degC]"""
        return gmsg.load(self._b, 0, 'u16', 'big')

    @property
    def temperature_scaled(self) -> float:
        x = self.temperature
        return float(x) * 0.0026703288319218739 + -45.0

    @property
    def temperature_degf(self) -> float:
        x = self.temperature
        return float(x) * 0.0048065918974593731 + -49.0

    @property
    def humidity(self) -> int:
        """[%RH]"""
        return gmsg.load(self._b, 3, 'u16', 'big')

    @property
    def humidity_scaled(self) -> float:
        x = self.humidity
        return float(x) * 0.0019073777370870527 + -6.0

    def ranges(self) -> list[gmsg.FieldRange]:
        """Byte ranges of the present fields (relative to data), in wire order; key is the attribute (None for
        padding and constants)."""
        out = []
        out.append(gmsg.FieldRange('temperature', 'temperature', 0, 3))
        out.append(gmsg.FieldRange('humidity', 'humidity', 3, 3 + 3))
        return out

    def print_to(self, p: gmsg.Printer) -> None:
        p.begin('Measurement')
        x = self.temperature
        p.key('temperature')
        p.int_value(x)
        p.conversion(float(x) * 0.0026703288319218739 + -45.0, 'degC')
        p.conversion(float(x) * 0.0048065918974593731 + -49.0, 'degF')
        x = self.humidity
        p.key('humidity')
        p.int_value(x)
        p.conversion(float(x) * 0.0019073777370870527 + -6.0, '%RH')
        p.end()

    def to_text(self, **options) -> str:
        return gmsg.to_text(self, **options)

    def __str__(self) -> str:
        return gmsg.to_text(self)

    def __repr__(self) -> str:
        return '<MeasurementView ' + gmsg.to_text(self, style='single_line') + '>'

    def to_struct(self) -> Measurement:
        """Decode into the message dataclass."""
        return Measurement.decode(self._b)


@_dataclass(slots=True)
class SerialNumber:
    # Response to ReadSerialNumber (datasheet 4.7) - two 16-bit words, each followed by its CRC.
    serial_high: int = 0
    serial_low: int = 0
    message_name: _ClassVar[str] = 'SerialNumber'
    min_wire_size: _ClassVar[int] = 6
    max_wire_size: _ClassVar[int] = 6
    wire_size: _ClassVar[int] = 6

    @property
    def serial(self) -> int:
        return gmsg.wrap_int((gmsg.i64(gmsg.to_int(self.serial_high) << 16) | gmsg.to_int(self.serial_low)), 'u32')

    @serial.setter
    def serial(self, v) -> None:
        value = gmsg.to_int(v)
        self.serial_high = gmsg.wrap_int(((value >> 16) & 65535), 'u16')
        self.serial_low = gmsg.wrap_int((value & 65535), 'u16')

    @staticmethod
    def read(r: gmsg.Reader) -> SerialNumber:
        m = SerialNumber()
        b0 = r.view(3)
        if gmsg.load_uint(b0, 2, 1, 'big') != gmsg.checksum.crc8_nrsc5.compute(b0, 0, 2): gmsg.fail(Err.BAD_CHECKSUM)
        v0 = gmsg.load(b0, 0, 'u16', 'big')
        m.serial_high = v0
        b0 = r.view(3)
        if gmsg.load_uint(b0, 2, 1, 'big') != gmsg.checksum.crc8_nrsc5.compute(b0, 0, 2): gmsg.fail(Err.BAD_CHECKSUM)
        v0 = gmsg.load(b0, 0, 'u16', 'big')
        m.serial_low = v0
        return m

    @staticmethod
    def write(w: gmsg.Writer, m: SerialNumber) -> None:
        w.write('u16', m.serial_high, 'big')
        w.uint(gmsg.checksum.crc8_nrsc5.compute(w.buf, w.pos - 2, w.pos), 1, 'big')
        w.write('u16', m.serial_low, 'big')
        w.uint(gmsg.checksum.crc8_nrsc5.compute(w.buf, w.pos - 2, w.pos), 1, 'big')

    @staticmethod
    def decode(data) -> SerialNumber:
        """Decode from bytes (trailing bytes are ignored). Raises gmsg.GmpError."""
        return SerialNumber.read(gmsg.Reader(data))

    @staticmethod
    def decode_with_extra(data) -> tuple[SerialNumber, int]:
        """Like decode(data): (message, extra), extra = bytes after the message (which decode ignores)."""
        r = gmsg.Reader(data)
        return SerialNumber.read(r), r.remaining

    def encode(self) -> bytes:
        w = gmsg.Writer()
        SerialNumber.write(w, self)
        return w.to_bytes()

    @staticmethod
    def view(data) -> SerialNumberView:
        """A validated zero-copy view over encoded bytes."""
        return SerialNumberView.from_bytes(data)

    def print_to(self, p: gmsg.Printer) -> None:
        p.begin('SerialNumber')
        p.key('serial_high')
        p.int_value(self.serial_high)
        p.key('serial_low')
        p.int_value(self.serial_low)
        p.key('serial')
        p.int_value(self.serial)
        p.note('computed')
        p.end()

    def to_text(self, **options) -> str:
        return gmsg.to_text(self, **options)

    def __str__(self) -> str:
        return gmsg.to_text(self)


