class MeasurementResponse:
    # 6 bytes read after a measure or heater command.
    max_frame = 6
    prefix_size = 0  # sync / start delimiter
    header_size = 0
    trailer_size = 0  # binary checksum
    suffix_size = 0  # end delimiter
    prefix = b''
    suffix = b''
    # The message views of this protocol.
    views = (MeasurementView,)
    messages = (Measurement,)
    escape = gmsg.NO_ESCAPE
    framing = gmsg.FixedConfig(sync=prefix, frame_size=6, escape=escape, suffix_len=0)

    @staticmethod
    def scan(b) -> gmsg.FrameScan:
        return gmsg.scan_fixed(b, MeasurementResponse.framing)

    @staticmethod
    def open(frame) -> gmsg.Opened:
        """Validate one complete frame (as found by scan()) and split it: header view and body."""
        frame = gmsg.to_bytes(frame)
        if len(frame) < 0: gmsg.fail(Err.TRUNCATED)
        fr = frame
        interior = memoryview(frame)[0:len(frame) - 0]
        if len(interior) < 0 + 0: gmsg.fail(Err.TRUNCATED)
        return gmsg.Opened(interior[0:len(interior) - 0])

    @staticmethod
    def select(f: gmsg.Opened):
        """The message view selected by the frame's type id. Raises GmpError (UnknownType, ...)."""
        return MeasurementView.from_bytes(f.body)

    @staticmethod
    def process(frame) -> gmsg.Received:
        """gmsg.StreamParser hook: the message and header views of a complete frame."""
        f = MeasurementResponse.open(frame)
        return gmsg.Received(MeasurementResponse.select(f), f.header)

    @staticmethod
    def parse(buffer):
        """Parse one frame at the start of buffer (whole-buffer / datagram mode): the message view."""
        buffer = gmsg.to_bytes(buffer)
        s = MeasurementResponse.scan(buffer)
        if s.kind == 'need_more': gmsg.fail(Err.TRUNCATED)
        if s.kind == 'skip': gmsg.fail(Err.BAD_SYNC if s.error == Err.NONE else s.error)
        return MeasurementResponse.select(MeasurementResponse.open(buffer[:s.size]))

    @staticmethod
    def decode(buffer):
        """Parse one frame and decode it into its message dataclass."""
        return MeasurementResponse.parse(buffer).to_struct()

    @staticmethod
    def stream(capacity: int | None = None) -> gmsg.StreamParser:
        """A stream parser for this protocol (default capacity: max_frame)."""
        return gmsg.StreamParser(MeasurementResponse, capacity)

    @staticmethod
    def endpoint(source: object = None, sink: object = None, **options: object) -> gmsg.Endpoint:
        """The stream joined to a byte source and sink (blocking; options: clock, idle, idle_timeout, send_policy, ...)."""
        return gmsg.Endpoint(MeasurementResponse, source, sink, **options)

    @staticmethod
    def async_endpoint(reader: object = None, writer: object = None, **options: object) -> gmsg.AsyncEndpoint:
        """The stream joined to an asyncio reader and writer (options: idle_timeout, send_policy, ...)."""
        return gmsg.AsyncEndpoint(MeasurementResponse, reader, writer, **options)

    @staticmethod
    def encode(m) -> bytes:
        """Encode a message of this protocol to a frame."""
        if isinstance(m, Measurement): return MeasurementResponse._encode0(m)
        gmsg.fail(Err.INVALID_VALUE, 'not a message of MeasurementResponse (use the message classes)')

    @staticmethod
    def _encode0(m: Measurement) -> bytes:
        w = gmsg.Writer()
        header_at = w.pos
        body_at = w.pos
        Measurement.write(w, m)
        body_len = w.pos - body_at
        if body_len > 6: gmsg.fail(Err.BAD_LENGTH)
        w.zeros(6 - body_len)
        out = w.to_bytes()
        return out


